on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata-se da redação dada ao antigo art. 223 do Código Penal (formas qualificadas do estupro e do atentado violento ao pudor): reclusão de oito a doze anos no caput, e de doze a vinte e cinco anos no parágrafo único. O dispositivo foi revogado pela Lei nº 12.015, de 2009.', '["Caput: reclusão de oito a doze anos.","Parágrafo único: reclusão de doze a vinte e cinco anos."]'::jsonb, '["Texto histórico: dispositivo revogado em 2009."]'::jsonb, 'Texto histórico, sem aplicação prática hoje.', '["Assertiva que aplica hoje as penas do antigo art. 223 erra."]'::jsonb, '[]'::jsonb, '["Art. 213 do Código Penal"]'::jsonb, 'under_review', 'claude'
