insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata-se da redação dada ao crime de epidemia (art. 267 do Código Penal): reclusão de dez a quinze anos. O dispositivo atual do Código Penal traz a estrutura vigente do tipo.', '["Pena de reclusão de 10 a 15 anos (redação histórica da Lei)."]'::jsonb, '["Texto histórico: confira o art. 267 do Código Penal vigente."]'::jsonb, 'Texto de alteração legislativa; consulte o Código Penal.', '["Assertiva que aplica a pena sem conferir a redação vigente do Código Penal erra."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
