insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Trata-se da redação dada ao crime de envenenamento de água potável ou de substância alimentícia ou medicinal (art. 270 do Código Penal): reclusão de dez a quinze anos.', '["Envenenamento de água potável: reclusão de 10 a 15 anos."]'::jsonb, '["O crime consta do rol de hediondos? Confira o art. 1º; a lista está no próprio artigo."]'::jsonb, 'Texto de alteração legislativa; a pena consta no Código Penal.', '["Assertiva que fixa em 5 a 10 anos a pena do envenenamento de água potável nessa alteração erra."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
